#!/bin/sh
# What a module's generated C header includes: exactly what its exported declarations need (docs/smith-lang.md, "The
# header"). Usage: sh tests/headers.sh path/to/smith
#   1. every committed generated header (include/smith/*.h with a `// Generated by smith` line) compiles on its own,
#      as C and as C++;
#   2. the rule, on small modules: an import only a body uses stays out; an import an export's type uses goes in; of two
#      imports the one that declares the name goes in (this needs the compiler inside smith, so a stage0 skips it); an
#      imported module whose type an export uses is included, and one only a body uses is not; an `#include` never goes
#      in; and each of these headers compiles on its own too.
set -u
case $1 in /*) smith=$1 ;; *) smith=$(pwd)/$1 ;; esac
here=$(cd "$(dirname "$0")/.." && pwd)
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT INT TERM
export XDG_CACHE_HOME=$work/xdg-cache
failures=0
total=0

ok() { # name, status (0: passed)
    total=$((total + 1))
    if [ "$2" -eq 0 ]; then
        echo "ok    $1"
    else
        failures=$((failures + 1))
        echo "FAIL  $1"
    fi
}

standalone() { # name, header, include path
    for mode in "c -std=gnu23" "c++ -std=c++23"; do
        out=$("$smith" cc -fsyntax-only -x $mode -I "$3" "$2" 2>&1)
        status=$?
        ok "$1 compiles alone (${mode%% *})" $status
        [ $status -eq 0 ] || echo "$out" | head -5
    done
}

has() { # name, header, include line (fixed text), wanted: yes or no
    if grep -qxF "$3" "$2"; then found=yes; else found=no; fi
    [ "$found" = "$4" ]
    status=$?
    if [ "$4" = yes ]; then ok "$1: $3 is in the header" $status; else ok "$1: $3 is not in the header" $status; fi
}

# 1. The committed headers.
for header in "$here"/include/smith/*.h; do
    grep -q '^// Generated by smith' "$header" || continue
    standalone "$(basename "$header")" "$header" "$here/include"
done

# 2. The rule.
mkdir -p "$work/src/t" "$work/include/t"
cd "$work/src" || exit 1
cat >t/body.smith <<'S'
module t::body;
import <stdio.h>;
export u32 body_only(u32 x) {
    c::printf("%u\n", x);
    return x;
}
S
cat >t/typed.smith <<'S'
module t::typed;
import <stdio.h>;
export c::FILE *typed_open(const char *path);
S
cat >t/two.smith <<'S'
module t::two;
import <string.h>;
import <stdio.h>;
export c::FILE *two_stream(void);
export u32 two_length(const char *s) {
    return (u32)c::strlen(s);
}
S
cat >t/tag.smith <<'S'
module t::tag;
import <sys/stat.h>;
import <stdio.h>;
export u32 tag_size(struct c::stat *info);
S
cat >t/include.smith <<'S'
module t::include;
#include <stdio.h>
#include <string.h>
export u32 include_only(u32 x) {
    puts("x");
    return x + (u32)strlen("y");
}
S
cat >t/point.smith <<'S'
module t::point;
export typedef struct {
    i32 x;
    i32 y;
} Point;
export Point origin(void) {
    return (Point){0, 0};
}
S
cat >t/uses.smith <<'S'
module t::uses;
import t::point;
export point::Point shifted(point::Point p);
S
cat >t/body_module.smith <<'S'
module t::body_module;
import t::point;
export i32 body_module_x(void) {
    return point::origin().x;
}
S
for module in body typed two tag include point uses body_module; do
    "$smith" cc --smith-header "t/$module.smith" -o "$work/include/t/$module.h" 2>"$work/err.$module"
    ok "$module: the header is written" $?
done

has "body: an import only a body uses" "$work/include/t/body.h" "#include <stdio.h>" no
has "typed: an import an export's type uses" "$work/include/t/typed.h" "#include <stdio.h>" yes
has "include: an #include" "$work/include/t/include.h" "#include <stdio.h>" no
has "include: an #include" "$work/include/t/include.h" "#include <string.h>" no
has "uses: an imported module an export's type uses" "$work/include/t/uses.h" '#include "t/point.h"' yes
has "body_module: an imported module only a body uses" "$work/include/t/body_module.h" '#include "t/point.h"' no
has "every header: the sized types' headers" "$work/include/t/body.h" "#include <stdint.h>" yes

if "$smith" cc --smith-which -x c 2>/dev/null | grep -q "token-hook yes"; then
    has "two: the import that declares the name" "$work/include/t/two.h" "#include <stdio.h>" yes
    has "two: the one that does not" "$work/include/t/two.h" "#include <string.h>" no
    has "tag: the import that declares the tag" "$work/include/t/tag.h" "#include <sys/stat.h>" yes
    has "tag: the one that does not" "$work/include/t/tag.h" "#include <stdio.h>" no
else
    echo "skip  two, tag: this smith has no clang with the token hook inside to ask"
fi

for module in body typed two tag include point uses body_module; do
    standalone "t/$module.h" "$work/include/t/$module.h" "$work/include"
done

echo
echo "$total header checks, $failures failed"
[ "$failures" -eq 0 ]
